
const WORDS=[{"id": 0, "w": "山脉", "p": "shānmài", "t": "名词", "m": "dãy núi, rặng núi", "coll": "连绵的山脉、穿越山脉", "s": "这条山脉绵延数百公里把两种不同的自然景观连接在一起。"}, {"id": 1, "w": "雕刻", "p": "diāokè", "t": "动词", "m": "điêu khắc, chạm trổ", "coll": "雕刻图案、雕刻作品", "s": "工匠在木板上雕刻图案一刀一刀使花纹逐渐清晰起来。"}, {"id": 2, "w": "干旱", "p": "gānhàn", "t": "形容词", "m": "khô hạn, hạn hán", "coll": "气候干旱、干旱地区", "s": "由于长期干旱，当地不得不寻找更加节约用水的耕作方法。"}, {"id": 3, "w": "耕地", "p": "gēngdì", "t": "名词", "m": "đất canh tác, đất trồng trọt", "coll": "保护耕地、耕地面积", "s": "合理利用土地既要考虑发展需要也要重视对耕地的保护。"}, {"id": 4, "w": "庄稼", "p": "zhuāngjia", "t": "名词", "m": "hoa màu", "coll": "种庄稼、庄稼长势", "s": "今年雨水充足田里的庄稼长势良好村民们都十分高兴。"}, {"id": 5, "w": "枯萎", "p": "kūwěi", "t": "形容词", "m": "khô héo", "coll": "花草枯萎、逐渐枯萎", "s": "缺少水分以后，窗边的花草逐渐枯萎叶子也失去了光泽。"}, {"id": 6, "w": "牲畜", "p": "shēngchù", "t": "名词", "m": "súc vật", "coll": "饲养牲畜、牲畜数量", "s": "过去这里的居民主要依靠种地和饲养牲畜维持生活。"}, {"id": 7, "w": "梯田", "p": "tītián", "t": "名词", "m": "ruộng bậc thang", "coll": "层层梯田、开垦梯田", "s": "层层梯田沿着山坡展开远远望去仿佛一幅精心绘制的画。"}, {"id": 8, "w": "壮丽", "p": "zhuànglì", "t": "形容词", "m": "tráng lệ, lộng lẫy, đẹp đẽ", "coll": "景色壮丽、壮丽山河", "s": "站在山顶眼前壮丽的景色让人久久不愿移开目光。"}, {"id": 9, "w": "依旧", "p": "yījiù", "t": "副词", "m": "như cũ", "coll": "依旧如此、依旧保持", "s": "多年以后，村里的道路变宽了那座老屋，却依旧保持着原来的样子。"}, {"id": 10, "w": "峡谷", "p": "xiágǔ", "t": "名词", "m": "khe sâu, hẻm núi", "coll": "峡谷深处、穿过峡谷", "s": "河水穿过狭长的峡谷在岩石之间发出低沉的声响。"}, {"id": 11, "w": "铺", "p": "pū", "t": "动词", "m": "trải, rải", "coll": "铺地毯、铺开画卷", "s": "工作人员在地上铺好地毯为接下来的展览做好准备。"}, {"id": 12, "w": "卷", "p": "juǎn", "t": "动词", "m": "cuốn, cuộn", "coll": "卷起来、卷成一团", "s": "收拾帐篷时，他先把防潮垫卷起来再装进背包。"}, {"id": 13, "w": "蔚蓝", "p": "wèilán", "t": "形容词", "m": "xanh biếc, xanh thẳm", "coll": "蔚蓝的天空、蔚蓝的大海", "s": "雨过天晴，蔚蓝的天空下远处的山峰显得格外清晰。"}, {"id": 14, "w": "漂浮", "p": "piāofú", "t": "动词", "m": "trôi, bồng bềnh", "coll": "漂浮在水面、云朵漂浮", "s": "几片落叶漂浮在水面上随着微风慢慢移向岸边。"}, {"id": 15, "w": "摇摆", "p": "yáobǎi", "t": "动词", "m": "đung đưa, lắc lư", "coll": "轻轻摇摆、左右摇摆", "s": "河边的树枝在风中轻轻摇摆树影也随之晃动起来。"}, {"id": 16, "w": "衬托", "p": "chèntuō", "t": "动词", "m": "làm nổi lên, tôn lên", "coll": "相互衬托、衬托景色", "s": "白色的云朵衬托着远处的青山使整个画面更有层次。"}, {"id": 17, "w": "盘旋", "p": "pánxuán", "t": "动词", "m": "lượn vòng, đi vòng", "coll": "在空中盘旋、盘旋而上", "s": "一只鸟在山谷上空盘旋过了许久才朝远处飞去。"}, {"id": 18, "w": "时而", "p": "shí'ér", "t": "副词", "m": "đôi lúc, thỉnh thoảng", "coll": "时而安静、时而响亮", "s": "山里的天气变化很快时而阳光明亮时而雾气弥漫。"}, {"id": 19, "w": "海拔", "p": "hǎibá", "t": "名词", "m": "độ cao so với mặt biển", "coll": "海拔高度、海拔较高", "s": "由于这里海拔较高，游客在安排行程时需要考虑自身的适应情况。"}, {"id": 20, "w": "瀑布", "p": "pùbù", "t": "名词", "m": "thác nước", "coll": "壮观的瀑布、瀑布飞流", "s": "远处的瀑布从悬崖上落下水声在山谷里不断回响。"}, {"id": 21, "w": "纵横", "p": "zònghéng", "t": "形容词", "m": "ngang dọc, ngang và dọc", "coll": "纵横交错、河道纵横", "s": "这片平原上河道纵横许多村庄都依水而建。"}, {"id": 22, "w": "汹涌", "p": "xiōngyǒng", "t": "形容词", "m": "cuộn trào, dâng", "coll": "波涛汹涌、汹涌的河水", "s": "暴雨过后，汹涌的河水冲过峡谷发出巨大的声响。"}, {"id": 23, "w": "目睹", "p": "mùdǔ", "t": "动词", "m": "chứng kiến, mắt thấy", "coll": "亲眼目睹、目睹变化", "s": "在这次走访中我们亲眼目睹了乡村生活的变化。"}, {"id": 24, "w": "重叠", "p": "chóngdié", "t": "动词", "m": "trùng điệp, chồng chéo", "coll": "层层重叠、相互重叠", "s": "远处的山峰层层重叠在晨雾中呈现出柔和的轮廓。"}, {"id": 25, "w": "雕塑", "p": "diāosù", "t": "动词／名词", "m": "điêu khắc; tác phẩm điêu khắc", "coll": "城市雕塑、雕塑作品", "s": "广场中央的雕塑取材于当地的传说吸引了许多游客驻足观看。"}, {"id": 26, "w": "毅力", "p": "yìlì", "t": "名词", "m": "nghị lực", "coll": "坚强的毅力、惊人的毅力", "s": "面对一次次失败，他凭借坚强的毅力终于完成了作品。"}, {"id": 27, "w": "杰出", "p": "jiéchū", "t": "形容词", "m": "phi thường, xuất sắc, tuyệt vời", "coll": "杰出贡献、杰出人才", "s": "这位科学家长期坚持研究为相关领域的发展作出了杰出贡献。"}, {"id": 28, "w": "震撼", "p": "zhènhàn", "t": "动词", "m": "chấn động, rung động, lay động", "coll": "深受震撼、震撼人心", "s": "当壮丽的梯田出现在眼前时他深受震撼。"}, {"id": 29, "w": "宫殿", "p": "gōngdiàn", "t": "名词", "m": "cung điện", "coll": "古代宫殿、宏伟的宫殿", "s": "这座宫殿经过多次修复仍然保留着许多精美的装饰。"}, {"id": 30, "w": "不禁", "p": "bùjīn", "t": "副词", "m": "không kìm được, không nhịn được", "coll": "不禁感叹、不禁想起", "s": "听到熟悉的旋律，她不禁想起了童年时的生活。"}, {"id": 31, "w": "曲子", "p": "qǔzi", "t": "名词", "m": "ca khúc", "coll": "演奏曲子、熟悉的曲子", "s": "老人坐在院子里用笛子吹奏着一支熟悉的曲子。"}, {"id": 32, "w": "采集", "p": "cǎijí", "t": "动词", "m": "thu thập, sưu tầm, thu nhặt", "coll": "采集样本、采集资料", "s": "研究人员沿着山路采集植物样本并记录发现的位置。"}, {"id": 33, "w": "种子", "p": "zhǒngzi", "t": "名词", "m": "hạt giống", "coll": "播撒种子、植物种子", "s": "春天，孩子们在老师指导下把种子播进了土里。"}, {"id": 34, "w": "稻谷", "p": "dàogǔ", "t": "名词", "m": "hạt lúa", "coll": "收获稻谷、晾晒稻谷", "s": "收获以后，村民们把稻谷摊在场地上晾晒。"}, {"id": 35, "w": "锲而不舍", "p": "qiè'érbùshě", "t": "成语", "m": "kiên nhẫn, miệt mài", "coll": "锲而不舍、锲而不舍的精神", "s": "只有保持锲而不舍的精神不断总结经验才可能逐步接近目标。"}, {"id": 36, "w": "开辟", "p": "kāipì", "t": "动词", "m": "khai thác, mở mang, xây dựng", "coll": "开辟道路、开辟新领域", "s": "他们在原有研究的基础上尝试开辟新的研究领域。"}, {"id": 37, "w": "心血", "p": "xīnxuè", "t": "名词", "m": "tâm huyết", "coll": "倾注心血、凝聚心血", "s": "这部作品凝聚着许多人的心血每一个细节都经过反复修改。"}, {"id": 38, "w": "辛勤", "p": "xīnqín", "t": "形容词", "m": "siêng năng, chăm chỉ", "coll": "辛勤劳动、辛勤耕耘", "s": "正是农民的辛勤劳动让荒坡逐渐变成了丰收的田野。"}, {"id": 39, "w": "阻拦", "p": "zǔlán", "t": "动词", "m": "ngăn cản, cản trở", "coll": "上前阻拦、受到阻拦", "s": "工作人员及时上前阻拦提醒游客不要进入正在施工的区域。"}, {"id": 40, "w": "生态", "p": "shēngtài", "t": "名词", "m": "sinh thái học", "coll": "生态环境、生态平衡", "s": "发展旅游业时，应当充分考虑当地的生态环境避免过度开发。"}, {"id": 41, "w": "审美", "p": "shěnměi", "t": "动词", "m": "thẩm mỹ", "coll": "审美能力、审美观念", "s": "欣赏不同地区的艺术有助于拓展学生的审美经验理解多样的表达方式。"}, {"id": 42, "w": "罕见", "p": "hǎnjiàn", "t": "形容词", "m": "hiếm thấy", "coll": "十分罕见、罕见的景象", "s": "这种景象在当地也十分罕见，因此吸引了许多人前来记录。"}, {"id": 43, "w": "珍稀", "p": "zhēnxī", "t": "形容词", "m": "quý hiếm", "coll": "珍稀植物、珍稀物种", "s": "保护区为多种珍稀植物提供了适宜生长的环境。"}, {"id": 44, "w": "陶醉", "p": "táozuì", "t": "动词", "m": "say sưa, ngây ngất", "coll": "陶醉其中、令人陶醉", "s": "悠扬的歌声回荡在山谷中让听众陶醉其中。"}, {"id": 45, "w": "遗产", "p": "yíchǎn", "t": "名词", "m": "di sản", "coll": "文化遗产、保护遗产", "s": "保护文化遗产不仅要保存实物也需要了解与之相关的生活传统。"}, {"id": 46, "w": "拥有", "p": "yōngyǒu", "t": "动词", "m": "sở hữu, có", "coll": "拥有资源、拥有机会", "s": "每个人都应该珍惜自己拥有的机会并为理想认真努力。"}];
const CHUNKS=[["这条山脉", "绵延数百公里", "把两种不同的自然景观", "连接在一起。"], ["工匠", "在木板上雕刻图案", "一刀一刀", "使花纹逐渐清晰起来。"], ["由于长期干旱，", "当地", "不得不寻找", "更加节约用水的耕作方法。"], ["合理利用土地", "既要考虑发展需要", "也要重视", "对耕地的保护。"], ["今年雨水充足", "田里的庄稼", "长势良好", "村民们都十分高兴。"], ["缺少水分以后，", "窗边的花草", "逐渐枯萎", "叶子也失去了光泽。"], ["过去", "这里的居民", "主要依靠种地", "和饲养牲畜维持生活。"], ["层层梯田", "沿着山坡展开", "远远望去", "仿佛一幅精心绘制的画。"], ["站在山顶", "眼前壮丽的景色", "让人", "久久不愿移开目光。"], ["多年以后，", "村里的道路变宽了", "那座老屋，", "却依旧保持着原来的样子。"], ["河水", "穿过狭长的峡谷", "在岩石之间", "发出低沉的声响。"], ["工作人员", "在地上铺好地毯", "为接下来的展览", "做好准备。"], ["收拾帐篷时，", "他", "先把防潮垫卷起来", "再装进背包。"], ["雨过天晴，", "蔚蓝的天空下", "远处的山峰", "显得格外清晰。"], ["几片落叶", "漂浮在水面上", "随着微风", "慢慢移向岸边。"], ["河边的树枝", "在风中轻轻摇摆", "树影", "也随之晃动起来。"], ["白色的云朵", "衬托着远处的青山", "使整个画面", "更有层次。"], ["一只鸟", "在山谷上空盘旋", "过了许久", "才朝远处飞去。"], ["山里的天气", "变化很快", "时而阳光明亮", "时而雾气弥漫。"], ["由于这里海拔较高，", "游客", "在安排行程时", "需要考虑自身的适应情况。"], ["远处的瀑布", "从悬崖上落下", "水声", "在山谷里不断回响。"], ["这片平原上", "河道纵横", "许多村庄", "都依水而建。"], ["暴雨过后，", "汹涌的河水", "冲过峡谷", "发出巨大的声响。"], ["在这次走访中", "我们", "亲眼目睹了", "乡村生活的变化。"], ["远处的山峰", "层层重叠", "在晨雾中", "呈现出柔和的轮廓。"], ["广场中央的雕塑", "取材于当地的传说", "吸引了", "许多游客驻足观看。"], ["面对一次次失败，", "他", "凭借坚强的毅力", "终于完成了作品。"], ["这位科学家", "长期坚持研究", "为相关领域的发展", "作出了杰出贡献。"], ["当壮丽的梯田", "出现在眼前时", "他", "深受震撼。"], ["这座宫殿", "经过多次修复", "仍然保留着", "许多精美的装饰。"], ["听到熟悉的旋律，", "她", "不禁想起了", "童年时的生活。"], ["老人", "坐在院子里", "用笛子吹奏着", "一支熟悉的曲子。"], ["研究人员", "沿着山路", "采集植物样本", "并记录发现的位置。"], ["春天，", "孩子们", "在老师指导下", "把种子播进了土里。"], ["收获以后，", "村民们", "把稻谷", "摊在场地上晾晒。"], ["只有保持锲而不舍的精神", "不断总结经验", "才可能", "逐步接近目标。"], ["他们", "在原有研究的基础上", "尝试开辟", "新的研究领域。"], ["这部作品", "凝聚着许多人的心血", "每一个细节", "都经过反复修改。"], ["正是农民的辛勤劳动", "让荒坡", "逐渐变成了", "丰收的田野。"], ["工作人员", "及时上前阻拦", "提醒游客", "不要进入正在施工的区域。"], ["发展旅游业时，", "应当", "充分考虑当地的生态环境", "避免过度开发。"], ["欣赏不同地区的艺术", "有助于", "拓展学生的审美经验", "理解多样的表达方式。"], ["这种景象", "在当地也十分罕见，", "因此", "吸引了许多人前来记录。"], ["保护区", "为多种珍稀植物", "提供了", "适宜生长的环境。"], ["悠扬的歌声", "回荡在山谷中", "让听众", "陶醉其中。"], ["保护文化遗产", "不仅要保存实物", "也需要", "了解与之相关的生活传统。"], ["每个人", "都应该珍惜", "自己拥有的机会", "并为理想认真努力。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai15-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/47 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),47)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共47个词语，点击 ↗ 学习该词语',totalLearned()+'/47 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===46;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<46){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:6};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课47个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课47个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [0, 19, 31], "5": [0, 19, 31], "8": [0, 19, 31], "11": [1, 23, 32], "14": [1, 32, 39], "17": [1, 32, 39], "20": [19, 31, 33], "23": [11, 12, 39], "26": [0, 19, 31], "29": [0, 19, 31], "32": [1, 11, 39], "35": [0, 19, 31], "38": [0, 19, 31], "41": [19, 31, 33], "44": [1, 11, 32]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如音频暂时无法播放，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的47个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第15课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第15课学习进度','第15课 · 47个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 47</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第15课';$('ntc-bookmark').textContent=student?total+'/47 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第15课学习进度</div><div style="padding:0 10px">'+total+'/47 个已学词语'+meter(total,47)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"山脉":"data:audio/mpeg;base64,","这条山脉绵延数百公里把两种不同的自然景观连接在一起。":"data:audio/mpeg;base64,","雕刻":"data:audio/mpeg;base64,","工匠在木板上雕刻图案一刀一刀使花纹逐渐清晰起来。":"data:audio/mpeg;base64,","干旱":"data:audio/mpeg;base64,","由于长期干旱，当地不得不寻找更加节约用水的耕作方法。":"data:audio/mpeg;base64,","耕地":"data:audio/mpeg;base64,","合理利用土地既要考虑发展需要也要重视对耕地的保护。":"data:audio/mpeg;base64,","庄稼":"data:audio/mpeg;base64,","今年雨水充足田里的庄稼长势良好村民们都十分高兴。":"data:audio/mpeg;base64,","枯萎":"data:audio/mpeg;base64,","缺少水分以后，窗边的花草逐渐枯萎叶子也失去了光泽。":"data:audio/mpeg;base64,","牲畜":"data:audio/mpeg;base64,","过去这里的居民主要依靠种地和饲养牲畜维持生活。":"data:audio/mpeg;base64,","梯田":"data:audio/mpeg;base64,","层层梯田沿着山坡展开远远望去仿佛一幅精心绘制的画。":"data:audio/mpeg;base64,","壮丽":"data:audio/mpeg;base64,","站在山顶眼前壮丽的景色让人久久不愿移开目光。":"data:audio/mpeg;base64,","依旧":"data:audio/mpeg;base64,","多年以后，村里的道路变宽了那座老屋，却依旧保持着原来的样子。":"data:audio/mpeg;base64,","峡谷":"data:audio/mpeg;base64,","河水穿过狭长的峡谷在岩石之间发出低沉的声响。":"data:audio/mpeg;base64,","铺":"data:audio/mpeg;base64,","工作人员在地上铺好地毯为接下来的展览做好准备。":"data:audio/mpeg;base64,","卷":"data:audio/mpeg;base64,","收拾帐篷时，他先把防潮垫卷起来再装进背包。":"data:audio/mpeg;base64,","蔚蓝":"data:audio/mpeg;base64,","雨过天晴，蔚蓝的天空下远处的山峰显得格外清晰。":"data:audio/mpeg;base64,","漂浮":"data:audio/mpeg;base64,","几片落叶漂浮在水面上随着微风慢慢移向岸边。":"data:audio/mpeg;base64,","摇摆":"data:audio/mpeg;base64,","河边的树枝在风中轻轻摇摆树影也随之晃动起来。":"data:audio/mpeg;base64,","衬托":"data:audio/mpeg;base64,","白色的云朵衬托着远处的青山使整个画面更有层次。":"data:audio/mpeg;base64,","盘旋":"data:audio/mpeg;base64,","一只鸟在山谷上空盘旋过了许久才朝远处飞去。":"data:audio/mpeg;base64,","时而":"data:audio/mpeg;base64,","山里的天气变化很快时而阳光明亮时而雾气弥漫。":"data:audio/mpeg;base64,","海拔":"data:audio/mpeg;base64,","由于这里海拔较高，游客在安排行程时需要考虑自身的适应情况。":"data:audio/mpeg;base64,","瀑布":"data:audio/mpeg;base64,","远处的瀑布从悬崖上落下水声在山谷里不断回响。":"data:audio/mpeg;base64,","纵横":"data:audio/mpeg;base64,","这片平原上河道纵横许多村庄都依水而建。":"data:audio/mpeg;base64,","汹涌":"data:audio/mpeg;base64,","暴雨过后，汹涌的河水冲过峡谷发出巨大的声响。":"data:audio/mpeg;base64,","目睹":"data:audio/mpeg;base64,","在这次走访中我们亲眼目睹了乡村生活的变化。":"data:audio/mpeg;base64,","重叠":"data:audio/mpeg;base64,","远处的山峰层层重叠在晨雾中呈现出柔和的轮廓。":"data:audio/mpeg;base64,","雕塑":"data:audio/mpeg;base64,","广场中央的雕塑取材于当地的传说吸引了许多游客驻足观看。":"data:audio/mpeg;base64,","毅力":"data:audio/mpeg;base64,","面对一次次失败，他凭借坚强的毅力终于完成了作品。":"data:audio/mpeg;base64,","杰出":"data:audio/mpeg;base64,","这位科学家长期坚持研究为相关领域的发展作出了杰出贡献。":"data:audio/mpeg;base64,","震撼":"data:audio/mpeg;base64,","当壮丽的梯田出现在眼前时他深受震撼。":"data:audio/mpeg;base64,","宫殿":"data:audio/mpeg;base64,","这座宫殿经过多次修复仍然保留着许多精美的装饰。":"data:audio/mpeg;base64,","不禁":"data:audio/mpeg;base64,","听到熟悉的旋律，她不禁想起了童年时的生活。":"data:audio/mpeg;base64,","曲子":"data:audio/mpeg;base64,","老人坐在院子里用笛子吹奏着一支熟悉的曲子。":"data:audio/mpeg;base64,","采集":"data:audio/mpeg;base64,","研究人员沿着山路采集植物样本并记录发现的位置。":"data:audio/mpeg;base64,","种子":"data:audio/mpeg;base64,","春天，孩子们在老师指导下把种子播进了土里。":"data:audio/mpeg;base64,","稻谷":"data:audio/mpeg;base64,","收获以后，村民们把稻谷摊在场地上晾晒。":"data:audio/mpeg;base64,","锲而不舍":"data:audio/mpeg;base64,","只有保持锲而不舍的精神不断总结经验才可能逐步接近目标。":"data:audio/mpeg;base64,","开辟":"data:audio/mpeg;base64,","他们在原有研究的基础上尝试开辟新的研究领域。":"data:audio/mpeg;base64,","心血":"data:audio/mpeg;base64,","这部作品凝聚着许多人的心血每一个细节都经过反复修改。":"data:audio/mpeg;base64,","辛勤":"data:audio/mpeg;base64,","正是农民的辛勤劳动让荒坡逐渐变成了丰收的田野。":"data:audio/mpeg;base64,","阻拦":"data:audio/mpeg;base64,","工作人员及时上前阻拦提醒游客不要进入正在施工的区域。":"data:audio/mpeg;base64,","生态":"data:audio/mpeg;base64,","发展旅游业时，应当充分考虑当地的生态环境避免过度开发。":"data:audio/mpeg;base64,","审美":"data:audio/mpeg;base64,","欣赏不同地区的艺术有助于拓展学生的审美经验理解多样的表达方式。":"data:audio/mpeg;base64,","罕见":"data:audio/mpeg;base64,","这种景象在当地也十分罕见，因此吸引了许多人前来记录。":"data:audio/mpeg;base64,","珍稀":"data:audio/mpeg;base64,","保护区为多种珍稀植物提供了适宜生长的环境。":"data:audio/mpeg;base64,","陶醉":"data:audio/mpeg;base64,","悠扬的歌声回荡在山谷中让听众陶醉其中。":"data:audio/mpeg;base64,","遗产":"data:audio/mpeg;base64,","保护文化遗产不仅要保存实物也需要了解与之相关的生活传统。":"data:audio/mpeg;base64,","拥有":"data:audio/mpeg;base64,","每个人都应该珍惜自己拥有的机会并为理想认真努力。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai15-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai15_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai15-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=47)||!p.memory)throw Error();if(!confirm('恢复第15课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<47;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<47&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第15课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

